def _cost_from_usage(usage):
    if not isinstance(usage, dict):
        return None
    value = usage.get("api_equivalent_cost_usd")
    if type(value) not in (int, float) or isinstance(value, bool):
        return None
    if not math.isfinite(value) or value < 0:
        return None
    return float(value)
